// ===== SHARED BOILERPLATE (same in every template) =====
let html = "";
const first = $input.first();
if (first) {
  const j = first.json;
  if (typeof j === 'string') {
    html = j;
  } else if (j && typeof j === 'object') {
    html = j.data || j.html || j.body || JSON.stringify(j);
  }
}
if (!html || html.trim() === "" || html === "{}") {
  return [{ json: { error: "No HTML received. Check the ScrapeUnblocker node output to ensure it is actually loading the page." } }];
}
// ===== END BOILERPLATE =====

// Search context (set before scraping)
let keyword = "", city = "";
try {
  const ctx = $('Set Keyword & City').first().json;
  keyword = ctx.keyword || "";
  city = ctx.city || "";
} catch (e) {}
const today = new Date().toISOString().split('T')[0];

// helpers
const grab = (s, re) => { const m = s.match(re); return m ? m[1].trim() : ""; };
const decode = (t) => t
  .replace(/&amp;/g, '&').replace(/&#39;/g, "'").replace(/&quot;/g, '"')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ').trim();

// One chunk per result card
const chunks = html.split(/class="hfpxzc"/i);

const leads = [];
for (let i = 1; i < chunks.length; i++) {
  const c = chunks[i];

  // NAME: read from the headline div INSIDE the card.
  // (The anchor's aria-label sits BEFORE the split point, so it belongs to the previous card — do not use it.)
  const name = decode(grab(c, /class="qBF1Pd[^"]*">\s*([^<]+?)\s*</i));
  if (!name) continue;

  const rating   = grab(c, /class="MW4etd">\s*([\d.]+)/i);
  const reviews  = grab(c, /aria-label="[\d.]+ stars\s*([\d,]+)\s*[Rr]eview/i).replace(/,/g, '');
  const category = decode(grab(c, /class="W4Efsd">\s*<span>\s*<span>\s*([^<]+?)\s*</i));
  const phone    = grab(c, /class="UsdlK">\s*([^<]+?)\s*</i);
  const website  = grab(c, /aria-label="Visit[^"]*website"[\s\S]*?href="([^"]+)"/i);

  // LAT / LNG: embedded in the place URL as !3dLAT!4dLNG
  const coord = c.match(/!3d(-?\d+\.\d+)!4d(-?\d+\.\d+)/);
  const lat = coord ? coord[1] : "";
  const lng = coord ? coord[2] : "";

  // ADDRESS: often absent for service businesses (Maps shows category + hours instead).
  // Best-effort: pick a W4Efsd text block that actually looks like an address (has a digit AND a comma).
  let address = "";
  const blocks = c.match(/class="W4Efsd">\s*<span>\s*<span>\s*([^<]+?)\s*</gi) || [];
  for (const b of blocks) {
    const txt = decode(b.replace(/class="W4Efsd">\s*<span>\s*<span>\s*/i, "").replace(/\s*<$/, ""));
    if (/\d/.test(txt) && /,/.test(txt)) { address = txt; break; }
  }

  leads.push({
    json: {
      Name: name,
      Rating: rating,
      Reviews: reviews,
      Category: category,
      Address: address,
      Latitude: lat,
      Longitude: lng,
      Phone: phone,
      Website: website,
      Keyword: keyword,
      City: city,
      Date: today
    }
  });
}

if (leads.length === 0) {
  return [{ json: { error: "HTML received but 0 listings parsed. Class names may have changed — inspect the ScrapeUnblocker output and adjust selectors.", scraped_chars: html.length } }];
}

return leads;

const seen = new Set();
const out = [];

for (const item of $input.all()) {
  const j = item.json;
  if (j.error) { out.push({ json: j }); continue; }

  const key = (j.Name || "").toLowerCase().trim();
  if (!key || seen.has(key)) continue;
  seen.add(key);

  const phone = (j.Phone || "").replace(/[^\d+]/g, "");

  out.push({
    json: {
      Name: j.Name || "",
      Rating: j.Rating || "",
      Reviews: j.Reviews || "",
      Category: j.Category || "",
      Address: j.Address || "",
      Latitude: j.Latitude || "",
      Longitude: j.Longitude || "",
      Phone: phone,
      Website: j.Website || "",
      Keyword: j.Keyword || "",
      City: j.City || "",
      Date: j.Date || ""
    }
  });
}

return out;

// HTTP node (Reverse Geocode) item pairing ki wajah se ye current lead deta hai
const lead = $('Clean & Dedupe Leads').item.json;

// Nominatim ka response is node ke input me hai
const geo = $json || {};
const a = geo.address || {};

// Full address (Nominatim ka display_name)
const fullAddress = geo.display_name || "";

// Clean/short address (country/state hata ke)
const parts = [
  a.house_number,
  a.road,
  (a.suburb || a.town || a.village || a.quarter),
  a.city,
  a.postcode
].filter(Boolean);
const cleanAddress = parts.join(", ");

const postcode = a.postcode || "";
const city = a.city || a.town || a.village || "";

// Quality flag: postcode na mile to pin shaky hai (jaise galat Google pin)
const geoConfidence = postcode ? "yes" : "check";

return [{
  json: {
    // --- saari previous fields waise ki waise ---
    ...lead,

    // --- address fields add ---
    Address: cleanAddress || fullAddress,
    FullAddress: fullAddress,
    Postcode: postcode,
    GeoCity: city,
    GeoConfidence: geoConfidence
  }
}];
